<template>
  <div class="me-message" v-title :data-title="title">
    <el-container class="">
      <el-main class="me-main">
        <el-card class="me-message-card">
          <div slot="header" class="me-message-header">
            <span>卫星地面融合网络社区-留言板</span>
          </div>
          
          <el-form :model="messageForm" :rules="rules" ref="messageForm" label-width="80px">
            <el-form-item label="昵称" prop="nickname">
              <el-input v-model="messageForm.nickname" placeholder="请输入您的昵称"></el-input>
            </el-form-item>
            <el-form-item label="留言内容" prop="content">
              <el-input type="textarea" v-model="messageForm.content" placeholder="请输入您的留言内容" rows="4"></el-input>
            </el-form-item>
            <el-form-item>
              <el-button type="primary" @click="submitMessage">提交留言</el-button>
            </el-form-item>
          </el-form>
        </el-card>
        
        <el-card class="me-message-list-card">
          <div slot="header" class="me-message-header">
            <span>留言列表</span>
          </div>
          
          <div v-for="(message, index) in messages" :key="index" class="me-message-item">
            <div class="me-message-item-header">
              <span class="me-message-item-nickname">{{message.nickname}}</span>
              <span class="me-message-item-time">{{message.time}}</span>
            </div>
            <div class="me-message-item-content">{{message.content}}</div>
            <div class="me-message-item-footer">
              <el-button size="small" type="text" @click="likeMessage(index)">
                <i class="el-icon-thumb"></i> {{message.likes}} 赞
              </el-button>
              <el-button size="small" type="text" @click="replyMessage(index)">
                <i class="el-icon-chat-line-round"></i> 回复
              </el-button>
            </div>
          </div>
        </el-card>
      </el-main>
    </el-container>
  </div>
</template>

<script>
  export default {
    name: 'MessageBoard',
    data() {
      return {
        messageForm: {
          nickname: '',
          content: ''
        },
        rules: {
          nickname: [
            { required: true, message: '请输入昵称', trigger: 'blur' },
            { min: 2, max: 20, message: '长度在 2 到 20 个字符', trigger: 'blur' }
          ],
          content: [
            { required: true, message: '请输入留言内容', trigger: 'blur' },
            { min: 5, message: '留言内容至少 5 个字符', trigger: 'blur' }
          ]
        },
        messages: [
          {
            nickname: '卫星爱好者',
            content: '请问有人了解卫星轨道计算的相关知识吗？想学习一下。',
            time: '2026-03-19 10:00',
            likes: 5
          },
          {
            nickname: '网络工程师',
            content: '卫星地面融合网络是未来的发展趋势，希望能和大家多交流。',
            time: '2026-03-18 15:30',
            likes: 8
          }
        ]
      }
    },
    computed: {
      title (){
        return '卫星地面融合网络社区-社区留言板'
      }
    },
    methods: {
      submitMessage() {
        this.$refs.messageForm.validate((valid) => {
          if (valid) {
            const newMessage = {
              nickname: this.messageForm.nickname,
              content: this.messageForm.content,
              time: new Date().toLocaleString(),
              likes: 0
            }
            this.messages.unshift(newMessage)
            this.messageForm = { nickname: '', content: '' }
            this.$message({
              type: 'success',
              message: '留言提交成功'
            })
          } else {
            return false
          }
        })
      },
      likeMessage(index) {
        this.messages[index].likes++
      },
      replyMessage(index) {
        this.$message({
          type: 'info',
          message: `回复 ${this.messages[index].nickname}`
        })
      }
    }
  }
</script>

<style scoped>
  .me-message {
  }

  .el-container {
    width: 960px;
  }

  .me-main {
    overflow: hidden;
  }

  .me-message-card {
    margin-bottom: 20px;
  }

  .me-message-list-card {
    margin-bottom: 20px;
  }

  .me-message-header {
    font-size: 18px;
    font-weight: 600;
    color: var(--secondary-color);
  }

  .me-message-item {
    padding: 15px 0;
    border-bottom: 1px solid var(--light-gray);
  }

  .me-message-item:last-child {
    border-bottom: none;
  }

  .me-message-item-header {
    margin-bottom: 10px;
  }

  .me-message-item-nickname {
    font-weight: 600;
    color: var(--primary-color);
    margin-right: 15px;
  }

  .me-message-item-time {
    font-size: 12px;
    color: var(--dark-gray);
  }

  .me-message-item-content {
    margin-bottom: 10px;
    line-height: 1.5;
  }

  .me-message-item-footer {
    text-align: right;
  }

  .el-button--text {
    color: var(--dark-gray);
  }

  .el-button--text:hover {
    color: var(--primary-color);
  }
</style>



